export function solve(base, bound, calls) {
  return calls.map((args) => base - [...bound, ...args].reduce((sum, x) => sum + x, 0));
}

referenceSolutions.typescript:
type Value = any;
export function solve(base: Value, bound: Value, calls: Value): Value {
  return calls.map(
    (args: Value) => base - [...bound, ...args].reduce((sum: Value, x: Value) => sum + x, 0),
  );
}
